import{_ as t,a as o,b as a}from"./chunks/2472d837de6cd4f056bf.DY7bboP3.js";import{_ as i,o as n,c as r,a5 as s}from"./chunks/framework.DNkHA0lr.js";const f=JSON.parse('{"title":"Disappear And Come Back Unrecognizable (12 Rules To Change Your Life)","description":"","frontmatter":{"title":"Disappear And Come Back Unrecognizable (12 Rules To Change Your Life)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md","filePath":"en/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md"}'),l={name:"en/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md"};function h(u,e,p,c,d,m){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="disappear-and-come-back-unrecognizable-12-rules-to-change-your-life" tabindex="-1">Disappear And Come Back Unrecognizable (12 Rules To Change Your Life) <a class="header-anchor" href="#disappear-and-come-back-unrecognizable-12-rules-to-change-your-life" aria-label="Permalink to &quot;Disappear And Come Back Unrecognizable (12 Rules To Change Your Life)&quot;">​</a></h1><p>Dan Koe · 2024-04-06 · <a href="https://thedankoe.com/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/reLmDf_PIvI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+t+'" alt=""></p><p>I don’t say this to sound arrogant.</p><p>But I’ve never had a problem with knowing what I want in the future.</p><p>When people say “I don’t know what I want,” what they’re really saying is “I don’t want to do the work it takes to get what I want.”</p><p>It’s not that you don’t know what you want. It’s that you know what you don’t want – meaning you know what you want – and are hiding from it it takes to get away from it.</p><p>I’ve always known what I wanted because it’s extremely simple to observe society and know what I don’t want:</p><ul><li>A job I hate</li><li>Work I hate</li><li>A body I hate</li><li>A partner I hate</li><li>A mind that hates me</li></ul><p>From that alone, it’s easy to figure out what I had to do:</p><ul><li>Become an entrepreneur no matter how many times I fail (it took 7 failures)</li><li>Gain the power to get rid of work I don’t want to do (writing on social media for leverage)</li><li>Go to the gym and work on my nutrition</li><li>Allow those 3 things to open up more opportunities in every domain of life</li><li>Let that path create a peaceful mind from the progressive overload of responsibility. Weights feel lighter as you get stronger.</li></ul><p>Everybody knows that some form of this path is what they are meant to do.</p><p>Your psyche craves actualization and transcendence. The depth of your being wants these things, but your ego is distracted by things it thinks it wants.</p><p>That’s the problem.</p><p>You don’t have a way to focus your mind.</p><p>You don’t have a plan for your future that has more gravity than the distractions in your life.</p><p>You struggle to maintain a long-term time horizon and get trapped in never-ending short-term stress-inducing tasks.</p><p>How would it feel to have one single framework that would determine the entirety of your success? One that you can refer to whenever you feel lost?</p><p>That’s what we are going to talk about.</p><h2 id="the-12-rules-of-creation" tabindex="-1">The 12 Rules Of Creation <a class="header-anchor" href="#the-12-rules-of-creation" aria-label="Permalink to &quot;The 12 Rules Of Creation&quot;">​</a></h2><blockquote><p>You need a plan. Because if you don’t have one, society does, and they’ve been planning your life for decades. – <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a></p></blockquote><p><img src="'+o+'" alt=""></p><p>You’ve been assigned goals by society since the day you were born.</p><p>These goals went on to frame how you viewed the world.</p><p>You learned skills to achieve those goals. You registered opportunities in alignment with those goals. Everything you experience in life is through the lens of the conscious or unconscious goals guiding the systems being formed in your head.</p><p>If we want to build a life of meaning, money, and impact, we must pursue our ideal future, create a story worth telling, and pass down that path to those who are ready to receive it.</p><p>After a decade of dancing between creative success and failure, I’ve found a big-picture framework that will bring you success in anything you do.</p><p>These patterns can be found in marketing, sales, human behavior, peak performance, psychology, stories, games, the structure of billion-dollar companies, successful product development, and anything involved in the process of creating and distributing value.</p><p>You will be using this as a guiding light for your life, but I encourage you to meditate on how it can be applied to your business, relationships, and conversations.</p><h3 id="anti-vision" tabindex="-1"><strong>Anti-Vision</strong> <a class="header-anchor" href="#anti-vision" aria-label="Permalink to &quot;**Anti-Vision**&quot;">​</a></h3><p>We start our story with an anti-vision.</p><p>The bane of your existence.</p><p>The first polar end of the worldview you will cultivate.</p><p>A positive-fear mechanism that kicks you into action.</p><p><em>Your anti-vision is the future that you do not want to live.</em></p><p>Start a running note of experiences you do not want to repeat.</p><ul><li>The material you don’t care to learn.</li><li>The work you don’t care to complete.</li><li>The arguments you don’t wish to have.</li></ul><p>You won’t get rid of them in an instant.</p><p>You are meant to identify them as problems to be solved.</p><h3 id="vision" tabindex="-1"><strong>Vision</strong> <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;**Vision**&quot;">​</a></h3><p>If you don’t have a vision, you are lost.</p><p>You can’t create outcomes, so you are doomed to the mechanical living of determined outcomes.</p><p>Every decision you make in any domain of your life must be filtered through your vision.</p><p>That is how you bring meaning to your actions and minimize distractions.</p><p>Write down exactly what you want out of life.</p><p><em>Don’t miss a detail, but realize this is an iterative process.</em></p><p>You won’t get it right the first time around, and you probably never will. That’s not the point. Spend 30 minutes generating a minimum viable vision. Come back to it often to add, subtract, and improve as your desires inevitably change with your failures.</p><h3 id="mission" tabindex="-1"><strong>Mission</strong> <a class="header-anchor" href="#mission" aria-label="Permalink to &quot;**Mission**&quot;">​</a></h3><p>Your mission is the most important thing in your life.</p><p>It is the bridge between what you do and don’t want.</p><p>The path you are forging toward your vision.</p><p><em>Anything that does not align with your mission is to be treated as a distraction.</em></p><p>Your mission evolves with awareness of new beliefs, opportunities, and knowledge.</p><p>Your mission requires faith. You can’t see the next step unless you take the first. And once you do, the second may be completely different than anything you imagined.</p><h3 id="standards" tabindex="-1"><strong>Standards</strong> <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;**Standards**&quot;">​</a></h3><p>You aren’t where you want to be because you are okay with where you are.</p><p><em>You don’t submit to your situation, you accept it so you can move forward.</em></p><p>Standards are absorbed from your environment.</p><ul><li>The friends you hang out with.</li><li>The books you read.</li><li>The media you consume.</li><li>The parents who raise you.</li><li>The teachers who knew it all.</li></ul><p>It may be time to make a change and sit with the ramifications.</p><h3 id="goals" tabindex="-1"><strong>Goals</strong> <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;**Goals**&quot;">​</a></h3><p>Big goals are for direction. Small goals are for clarity.</p><p>You don’t need motivation when the task in front of you is so stupidly simple that you can’t help but complete it.</p><p>Break down your vision into goals by decade, year, month, week, and day.</p><p>They are your guide, not your master.</p><p>Be stubborn with vision and loose with details.</p><p>Your goals will change as you do, be okay with that.</p><h3 id="projects" tabindex="-1"><strong>Projects</strong> <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;**Projects**&quot;">​</a></h3><p>Learning comes from struggle, not memorization.</p><p>You need a series of tangible projects to build that will actualize your vision.</p><ul><li>Turn your goals into projects.</li><li>Architect an outline.</li><li>Determine milestones</li><li>Set deadlines</li><li>Map out areas of research.</li></ul><p>Build, then learn. Start the project, expose your lack of knowledge and skill, and use that as a reference point for your education.</p><h3 id="education" tabindex="-1"><strong>Education</strong> <a class="header-anchor" href="#education" aria-label="Permalink to &quot;**Education**&quot;">​</a></h3><p>You aren’t where you want to be because you aren’t as smart as you think you are.</p><p>With every project, there is a skill set and mindset required to complete the project.</p><p>Daily self-education must become a cornerstone habit in your life. If you stop learning, you stop evolving. Opportunities stop presenting themselves, and you get trapped in your current stage of development.</p><p>Education is the fuel for experimentation.</p><h3 id="limitations" tabindex="-1"><strong>Limitations</strong> <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;**Limitations**&quot;">​</a></h3><p>A fool becomes rich at the expense of everything good in life.</p><p>A creative becomes rich at the expense of his choice.</p><p>Limitations on your goals force creativity.</p><p>The question is, what are you <em>not</em> willing to sacrifice to achieve your goals?</p><p>The creative challenge appears when you attempt to achieve a goal without betraying your vision.</p><p>You can become rich without sacrificing your family.</p><p>You can become healthy without sacrificing your work.</p><p>You can become valuable without sacrificing what makes life worth living.</p><h3 id="levers" tabindex="-1"><strong>Levers</strong> <a class="header-anchor" href="#levers" aria-label="Permalink to &quot;**Levers**&quot;">​</a></h3><p>Every day, you need priority tasks that move the lever toward your projects, goals, and vision from the ground up.</p><p>These are often perceived as boring fundamentals without the cultivation of a sense of mastery.</p><p>Do what needs to be done, but grip your vision as the anchor into the unknown. If you aren’t making progress, it’s because you aren’t moving levers, even if you think you are.</p><p>Writing is the main lever in my creator business (and almost any other modern business). This is what I teach in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>, and what we help people that want personalized help and feedback with in <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>.</p><h3 id="challenge" tabindex="-1"><strong>Challenge</strong> <a class="header-anchor" href="#challenge" aria-label="Permalink to &quot;**Challenge**&quot;">​</a></h3><p>When a novice plays against a master, neither has fun.</p><p>The novice becomes anxious while the master becomes bored.</p><p>When your skill is the perfect match for the challenge of a situation, the world goes quiet, and you move forward with grace.</p><p>Challenge is the source of enjoyment.</p><p>Enjoyment is found on the tightrope between boredom and anxiety. At the edge of your abilities.</p><p>The path to meaningful living is often found in a simple shift in perspective.</p><h3 id="curiosity" tabindex="-1"><strong>Curiosity</strong> <a class="header-anchor" href="#curiosity" aria-label="Permalink to &quot;**Curiosity**&quot;">​</a></h3><p>Be willing to steer off course and discover new potential.</p><p>It is too easy to lock ourselves in the mechanical routine we were trying to escape.</p><p>Be curious.</p><p>Dive deep into your interests.</p><p>Let few questions go unanswered.</p><p>Avoid getting locked into paradigms and beliefs that narrow your mind on one idolized path.</p><p>Your vision is like a battery. You must fuel it with experience, education, and misdirection.</p><h3 id="experimentation" tabindex="-1"><strong>Experimentation</strong> <a class="header-anchor" href="#experimentation" aria-label="Permalink to &quot;**Experimentation**&quot;">​</a></h3><p>If you only do the same thing as everyone else, you are bound to the results of everyone else.</p><ul><li>Research processes that others teach, the ones they have seen success with.</li><li>Try multiple techniques to see which ones get <em>you</em> the best results.</li><li>Create your own process that you can stay consistent with.</li></ul><p>In fitness, try different training and nutrition programs. In relationships, try therapy or self-help books. In business, try cold outreach and organic content.</p><p>Avoid becoming dogmatic about the single right way. There is no right way, there is only your way, and that isn’t bound to stay the same as different levels of the game require different methods to complete them.</p><p>When you are lost, run through this process.</p><p>When your relationships are failing, run through this process. When your business won’t get off the ground, run through this process.</p><p>Every successful interaction with reality starts and ends with a clear image of the want, clarity on how to achieve it, and creative execution to acquire rare results.</p><h2 id="making-better-decisions" tabindex="-1">Making Better Decisions <a class="header-anchor" href="#making-better-decisions" aria-label="Permalink to &quot;Making Better Decisions&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>You aren’t where you want to be because:</p><ul><li>You didn’t make the choices that led to a purposeful career.</li><li>You didn’t make the choices that led to fulfilling relationships.</li><li>You didn’t make the choices that led to a healthy and aesthetic body.</li></ul><p>You, right now, are the manifestation of your past choices.</p><p>So, if you want to take control of who you become, your choices are of utmost importance.</p><p>There are 2 things here:</p><ol><li>Who you want to become – perspective and zooming out.</li><li>The choices that will take you there – perception and zooming in.</li></ol><p>The good life is created by constant reminder of your vision and programming the identity that would actualize it through aligned action.</p><p>Better decisions come from perspective and perception.</p><p>Every day, zoom out and remind yourself of what you don’t want. You don’t need to focus on what you want, because that will make itself apparent through your choices.</p><p>Hold that frame at the top of your mind.</p><p>Do not allow distractions to penetrate it.</p><p>Any time a choice comes up, zoom out and align.</p><p>“Will this benefit the future I am trying to create?”</p><p>Then, be decisive. Make the decision.</p><p>Allow failure into your life so you can correct your behavior the next time around.</p><p>Awareness is a cure.</p><p>You don’t have to quit all of your bad habits. You just have to view them and their consequences through the lens of your vision for long enough.</p><p>Dan</p>',135)])])}const w=i(l,[["render",h]]);export{f as __pageData,w as default};
